import{_ as t,o,c as a,a5 as r}from"./chunks/framework.D2XEhk-n.js";const u=JSON.parse('{"title":"What is JUCE?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-juce.md","filePath":"guide/what-is-juce.md","lastUpdated":1790686605000}'),s={name:"guide/what-is-juce.md"};function n(i,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-is-juce" tabindex="-1">What is JUCE? <a class="header-anchor" href="#what-is-juce" aria-label="Permalink to &quot;What is JUCE?&quot;">​</a></h1><p><strong>JUCE is a cross-platform C++ framework for building audio applications, audio plug-ins, and the GUIs that go with them.</strong> You write your program once against JUCE&#39;s classes and it compiles for macOS, Windows, Linux, iOS, and Android.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> The same code can also be wrapped as a VST3, AU, AUv3, AAX, or LV2 plug-in.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup></p><p>The name began as <em>Jules&#39; Utility Class Extensions</em>, after its original author, Julian &quot;Jules&quot; Storer. It is now owned by PACE Anti-Piracy, which acquired it from ROLI in 2020 (see <a href="./history.html">History</a>).<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="what-problem-does-it-solve" tabindex="-1">What problem does it solve? <a class="header-anchor" href="#what-problem-does-it-solve" aria-label="Permalink to &quot;What problem does it solve?&quot;">​</a></h2><p>Writing audio software means dealing with several hard problems at once:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Without JUCE</th><th>With JUCE</th></tr></thead><tbody><tr><td><strong>Audio I/O</strong></td><td>CoreAudio, WASAPI, ASIO, ALSA, JACK, Oboe… each with its own API and threading rules<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></td><td>One <code>AudioDeviceManager</code> and one callback</td></tr><tr><td><strong>Plug-in formats</strong></td><td>A separate SDK and wrapper per format (VST3, AU, AAX, LV2) and per host quirk</td><td>Write one <code>AudioProcessor</code>; JUCE generates each format</td></tr><tr><td><strong>GUI</strong></td><td>Cocoa, Win32, X11/Wayland, UIKit, Android views</td><td>One <code>Component</code> tree drawn with one <code>Graphics</code> API</td></tr><tr><td><strong>Everything else</strong></td><td>Strings, files, threads, networking, XML/JSON, maths</td><td><code>juce_core</code>, one consistent library</td></tr></tbody></table><p>The trade-off: JUCE is a <em>framework</em>, so it owns the event loop and the application lifecycle. You fill in the parts it calls, rather than calling it from your own <code>main()</code>.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li><strong>24 modules</strong> of C++ source<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup> (see the <a href="./../reference/module-map.html">module map</a>). Each is a folder you add to your build; there are no pre-built binaries.</li><li><strong>Tools</strong> in <code>extras/</code>: <ul><li><strong>Projucer</strong>, a project generator and editor (the older way to configure projects)<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li><li><strong>AudioPluginHost</strong>, a small host for testing plug-ins</li><li><strong>UnitTestRunner</strong>, <strong>BinaryBuilder</strong>, and <strong>AudioPerformanceTest</strong></li></ul></li><li><strong>CMake API</strong> (<code>juce_add_plugin</code>, <code>juce_add_gui_app</code>, …), the modern way to build (see <a href="./build-systems.html">Build systems</a>).<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li><strong>Examples</strong> in <code>examples/</code>, including the <strong>DemoRunner</strong> app that bundles most demos.</li></ul><h2 id="the-five-ideas-that-explain-most-of-juce" tabindex="-1">The five ideas that explain most of JUCE <a class="header-anchor" href="#the-five-ideas-that-explain-most-of-juce" aria-label="Permalink to &quot;The five ideas that explain most of JUCE&quot;">​</a></h2><ol><li><strong>Everything is a module.</strong> Modules are layered: <code>juce_core</code> at the bottom, plug-in wrappers at the top. Each module lists its dependencies in its header. → <a href="./architecture.html">Architecture</a></li><li><strong>Two important threads.</strong> The <em>message thread</em> runs the GUI and events; the <em>audio thread</em> runs your DSP and must never block. Much of JUCE&#39;s design exists to move data safely between them. → <a href="./core-concepts.html#threads">Core concepts</a></li><li><strong>Components draw themselves.</strong> A GUI is a tree of <code>Component</code> objects, each with <code>paint()</code> and <code>resized()</code>. → <a href="./core-concepts.html#components">Core concepts</a></li><li><strong>An <code>AudioProcessor</code> is the unit of audio work.</strong> Plug-ins, graph nodes, and hosted third-party plug-ins all share this interface. → <a href="./plugin-anatomy.html">Anatomy of a plug-in</a></li><li><strong>State lives in trees.</strong> <code>ValueTree</code> plus listeners gives you undo, serialisation, and UI binding almost for free. → <a href="./core-concepts.html#state">Core concepts</a></li></ol><h2 id="where-it-fits" tabindex="-1">Where it fits <a class="header-anchor" href="#where-it-fits" aria-label="Permalink to &quot;Where it fits&quot;">​</a></h2><p>JUCE&#39;s own README describes it as a framework for desktop and mobile applications, including audio plug-ins and plug-in hosts.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1:2]</a></sup> The design choices visible in the source (the message thread, the audio thread, <code>AudioProcessor</code>) are made with real-time audio in mind, so audio work is the natural fit. General desktop apps are possible too.</p><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p>The JUCE modules are dual-licensed:<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><ul><li><strong>AGPLv3.</strong> Free to use, but if you distribute your software (or let people use it over a network), you must release its source under the AGPLv3 as well.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li><strong>Commercial JUCE licence.</strong> Governed by the <a href="https://juce.com/legal/juce-9-licence/" target="_blank" rel="noreferrer">JUCE 9 End User Licence Agreement</a>. You need this for closed-source products. The <a href="https://juce.com/get-juce/#licensing-faq" target="_blank" rel="noreferrer">licensing FAQ</a> explains the available tiers.</li></ul><p>The examples use the permissive ISC licence. Bundled third-party code keeps its own licence, listed in the SPDX bill of materials (<code>JUCE.spdx.json</code>). Plug-in SDKs such as AAX have their own agreements too.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup> See <a href="https://github.com/andrewh/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer"><code>LICENSE.md</code></a>.</p><div class="warning custom-block"><p class="custom-block-title">Not legal advice</p><p>This is a summary of the licence files, not legal advice. The JUCE team says it cannot confirm compliance for specific usage, so read the EULA and licensing FAQ and take your own advice before shipping a product.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7:1]</a></sup></p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>For how the pieces relate: <a href="./architecture.html">Architecture</a></li><li>For the vocabulary: <a href="./../reference/glossary.html">Glossary</a></li><li>For a structured way to study: <a href="./learning-path.html">Learning path</a></li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://github.com/andrewh/JUCE/blob/master/README.md" target="_blank" rel="noreferrer"><code>README.md</code></a>: opening paragraph (VST, VST3, AU, AUv3, AAX and LV2 plug-ins and hosts; desktop and mobile applications) and &quot;Deployment Targets&quot; (macOS, Windows, Linux, iOS, Android). <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a> <a href="#fnref1:2" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>See the sourced timeline on <a href="./history.html">History</a>, which cites Wikipedia, MusicRadar, and Synthtopia for the 2020 sale from ROLI to PACE. <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>Backends present under <a href="https://github.com/andrewh/JUCE/blob/master/modules/juce_audio_devices/native" target="_blank" rel="noreferrer"><code>modules/juce_audio_devices/native/</code></a>: CoreAudio, WASAPI, ASIO, DirectSound, ALSA, JACK, Oboe, OpenSL and iOS audio. The description of each having its own API is this site&#39;s summary. <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><code>ls modules/</code> in this repository lists 24 <code>juce_*</code> folders (JUCE 9.0.3). See the <a href="./../reference/module-map.html">module map</a>, generated from the headers. Modules ship as source: the README&#39;s CMake and Projucer sections describe building them into your project. <a href="#fnref4" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p>The <a href="https://github.com/andrewh/JUCE/blob/master/extras" target="_blank" rel="noreferrer"><code>extras/</code></a> folder contains <code>Projucer</code>, <code>AudioPluginHost</code>, <code>UnitTestRunner</code>, <code>BinaryBuilder</code>, and <code>AudioPerformanceTest</code>, among others. <a href="#fnref5" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p><a href="https://github.com/andrewh/JUCE/blob/master/docs/CMake%20API.md" target="_blank" rel="noreferrer"><code>docs/CMake API.md</code></a>, and the examples in <a href="https://github.com/andrewh/JUCE/blob/master/examples" target="_blank" rel="noreferrer"><code>examples/</code></a> including <code>examples/DemoRunner</code>. <a href="#fnref6" class="footnote-backref">↩︎</a></p></li><li id="fn7" class="footnote-item"><p><a href="https://github.com/andrewh/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer"><code>LICENSE.md</code></a>: dual licence, the JUCE 9 EULA and licensing FAQ links, the ISC licence for examples, the SPDX bill of materials, and the statement that the JUCE team cannot provide compliance confirmations or legal advice. <a href="#fnref7" class="footnote-backref">↩︎</a> <a href="#fnref7:1" class="footnote-backref">↩︎</a></p></li><li id="fn8" class="footnote-item"><p><a href="https://www.gnu.org/licenses/agpl-3.0.en.html" target="_blank" rel="noreferrer">GNU AGPLv3 text</a>, section 13 (remote network interaction). <a href="#fnref8" class="footnote-backref">↩︎</a></p></li><li id="fn9" class="footnote-item"><p><a href="https://github.com/andrewh/JUCE/blob/master/LICENSE.md" target="_blank" rel="noreferrer"><code>LICENSE.md</code></a> says bundled third-party software keeps its own terms; the AAX signing requirement is in <a href="https://github.com/andrewh/JUCE/blob/master/README.md#aax-plug-ins" target="_blank" rel="noreferrer"><code>README.md</code>, &quot;AAX Plug-Ins&quot;</a>. <a href="#fnref9" class="footnote-backref">↩︎</a></p></li></ol></section>',23)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
